(() => {
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),mini=document.getElementById('minimap'),mctx=mini.getContext('2d');
const W=canvas.width,H=canvas.height,TAU=Math.PI*2;
const ui={};['level','xp-label','xp-fill','hp-text','hp-fill','mana-text','mana-fill','wave-label','objective-title','objective-sub','quest-title','quest-copy','quest-fill','remain-count','kill-count','relic-count','relic-slots','weapon-name','weapon-stat','depth-stat','time-stat','gold-stat','crit-stat','toast','pickup-hint','spin-status','potion-count','log-text','run-number','floor-label','start-screen','pause-screen','levelup-screen','upgrade-cards','end-screen','end-kicker','end-title','end-copy','start-btn','restart-btn','pause-btn','resume-btn','sound-btn'].forEach(id=>ui[id]=document.getElementById(id));
const keys={},mouse={x:W/2,y:H/2,down:false};let state='menu',last=0,elapsed=0,spawnTimer=0,toastTimer=0;
let player,enemies=[],projectiles=[],enemyShots=[],particles=[],orbs=[],drops=[],decor=[],relics=[],wave=1,waveKills=0,totalKills=0,gold=0,potions=2,run=1,screenShake=0,bossSpawned=false,damageFlash=0;
const waveTargets=[8,12,16,1];
const upgrades=[
 {icon:'⚔',title:'Keen Edge',copy:'Knife damage increased by 25%.',apply:()=>player.damage*=1.25},
 {icon:'✦',title:'Fleet Footed',copy:'Move 12% faster and dash recharges sooner.',apply:()=>{player.speed*=1.12;player.dashMax=Math.max(2.4,player.dashMax-.6)}},
 {icon:'♥',title:'Bloodwell',copy:'Gain 25 maximum vitality and heal fully.',apply:()=>{player.maxHp+=25;player.hp=player.maxHp}},
 {icon:'☼',title:'Deadeye',copy:'Critical chance increased by 8%.',apply:()=>player.crit+=.08},
 {icon:'◈',title:'Deep Reserves',copy:'Focus capacity +20. Whirlwind costs less.',apply:()=>player.maxMana+=20},
 {icon:'⌁',title:'Quick Hands',copy:'Knife throw cooldown reduced by 15%.',apply:()=>player.attackRate=Math.max(.18,player.attackRate*.85)}
];
const rand=(a,b)=>a+Math.random()*(b-a),clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
function initRun(){player={x:W/2,y:H/2,hp:100,maxHp:100,mana:60,maxMana:60,speed:178,damage:26,attackRate:.42,attackCd:0,crit:.08,level:1,xp:0,nextXp:30,dashCd:0,dashMax:4.2,dashTime:0,invuln:0,spinCd:0,spinMax:8,spinTime:0,aimX:1,aimY:0};enemies=[];projectiles=[];enemyShots=[];particles=[];orbs=[];drops=[];relics=[];wave=1;waveKills=0;totalKills=0;gold=0;potions=2;elapsed=0;spawnTimer=.6;bossSpawned=false;screenShake=0;damageFlash=0;buildDecor();updateUI();state='playing';ui['start-screen'].classList.add('hidden');ui['end-screen'].classList.add('hidden');ui['pause-screen'].classList.add('hidden');ui['levelup-screen'].classList.add('hidden');say('The dead have noticed you.');}
function buildDecor(){decor=[];for(let i=0;i<42;i++)decor.push({x:rand(22,W-22),y:rand(22,H-22),r:rand(9,24),type:Math.random()<.54?'stone':'crack',rot:rand(0,TAU)});}
function say(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=2.2;ui['log-text'].textContent=text;}
function updateUI(){if(!player)return;ui.level.textContent=String(player.level).padStart(2,'0');ui['xp-label'].textContent=`${Math.floor(player.xp)} / ${player.nextXp}`;ui['xp-fill'].style.width=`${100*player.xp/player.nextXp}%`;ui['hp-text'].textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;ui['hp-fill'].style.width=`${100*player.hp/player.maxHp}%`;ui['mana-text'].textContent=`${Math.floor(player.mana)} / ${player.maxMana}`;ui['mana-fill'].style.width=`${100*player.mana/player.maxMana}%`;ui['wave-label'].textContent=`WAVE ${Math.min(wave,4)} / 4`;ui['remain-count'].textContent=`${Math.max(0,waveTargets[wave-1]-waveKills)} / ${waveTargets[wave-1]}`;ui['quest-fill'].style.width=`${100*waveKills/waveTargets[wave-1]}%`;ui['kill-count'].textContent=totalKills;ui['gold-stat'].textContent=gold;ui['depth-stat'].textContent=String(wave).padStart(2,'0');ui['time-stat'].textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;ui['crit-stat'].textContent=`${Math.round(player.crit*100)}%`;ui['potion-count'].textContent=potions;ui['spin-status'].textContent=player.spinCd<=0?'READY':`${Math.ceil(player.spinCd)}s`;ui['relic-count'].textContent=`${relics.length} / 4`;ui['relic-slots'].innerHTML=Array.from({length:4},(_,i)=>relics[i]?`<div class="relic-slot" title="${relics[i].name}">${relics[i].icon}</div>`:'<div class="empty-relic"><span>＋</span><small>EMPTY</small></div>').join('');ui['floor-label'].textContent=wave===1?'FLOOR I · THE HOLLOW':`FLOOR ${['','I','II','III','IV'][wave]} · ${['','THE HOLLOW','BONE CHAPEL','ASHEN CATACOMBS','THE DREAD KNIGHT'][wave]}`;ui['objective-title'].textContent=['','THE HOLLOW','BONE CHAPEL','ASHEN CATACOMBS','THE DREAD KNIGHT'][wave];ui['objective-sub'].textContent=wave===4?'Defeat the keeper of the Vale':'Slay the restless dead';ui['quest-title'].textContent=wave===4?'THE DREAD KNIGHT':'A QUIET HOLLOW';ui['quest-copy'].textContent=wave===4?'The keeper has risen. End the curse.':'Clear the restless dead. Something stirs below.';}
function spawnEnemy(type){let side=Math.floor(rand(0,4)),x=side===0?-25:side===1?W+25:rand(35,W-35),y=side===2?-25:side===3?H+25:rand(35,H-35);let e={x,y,type,r:13,hp:45,maxHp:45,speed:42,damage:11,attackCd:rand(.3,1),flash:0,phase:rand(0,TAU),value:5};if(type==='ghoul'){e.r=10;e.hp=e.maxHp=27;e.speed=66;e.damage=8;e.value=4}if(type==='brute'){e.r=19;e.hp=e.maxHp=105;e.speed=27;e.damage=18;e.value=10}if(type==='cultist'){e.r=12;e.hp=e.maxHp=42;e.speed=28;e.damage=8;e.range=190;e.value=7}if(type==='boss'){e.r=28;e.hp=e.maxHp=520;e.speed=24;e.damage=22;e.value=50;e.boss=true;}enemies.push(e);}
function enemySpawn(){if(wave===4){if(!bossSpawned){spawnEnemy('boss');bossSpawned=true;say('THE DREAD KNIGHT descends!');}return}let n=waveKills+enemies.length;let target=waveTargets[wave-1];if(n>=target)return;let r=Math.random(),type=r<.5?'ghoul':r<.82?'husk':'cultist';if(n>target*.65&&r>.78)type='brute';spawnEnemy(type);}

input.newString:
if(n>target*.65&&r>.78)type='brute';spawnEnemy(type);}
function nearestEnemy(){let best=null,bd=Infinity;for(const e of enemies){let d=dist(player,e);if(d<bd){bd=d;best=e}}return best;}
function throwKnife(){if(player.attackCd>0)return;let target=nearestEnemy(),dx=target?target.x-player.x:mouse.x-player.x,dy=target?target.y-player.y:mouse.y-player.y,len=Math.hypot(dx,dy)||1;dx/=len;dy/=len;player.aimX=dx;player.aimY=dy;let crit=Math.random()<player.crit;projectiles.push({x:player.x+dx*14,y:player.y+dy*14,vx:dx*440,vy:dy*440,r:5,life:1.15,damage:player.damage*(crit?2:1),crit,spin:false});player.attackCd=player.attackRate;burst(player.x+dx*13,player.y+dy*13,'#d7bd85',3);}
function whirlwind(){if(player.spinCd>0||player.mana<20)return;player.mana-=20;player.spinCd=player.spinMax;player.spinTime=.42;for(let i=0;i<16;i++){let a=TAU*i/16;projectiles.push({x:player.x+Math.cos(a)*15,y:player.y+Math.sin(a)*15,vx:Math.cos(a)*300,vy:Math.sin(a)*300,r:6,life:.42,damage:player.damage*.9,crit:false,spin:true});}for(let e of enemies)if(dist(player,e)<83){e.hp-=player.damage*1.35;e.flash=.15;if(e.hp<=0)killEnemy(e);}burst(player.x,player.y,'#9bafaf',23);say('SHADOW WHIRLWIND');}
function dash(){if(player.dashCd>0)return;let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(!dx&&!dy){dx=player.aimX;dy=player.aimY}let l=Math.hypot(dx,dy)||1;player.x=clamp(player.x+dx/l*74,28,W-28);player.y=clamp(player.y+dy/l*74,28,H-28);player.dashCd=player.dashMax;player.dashTime=.22;player.invuln=.38;for(let i=0;i<10;i++)particles.push({x:player.x-dx/l*i*5,y:player.y-dy/l*i*5,vx:rand(-20,20),vy:rand(-20,20),life:.36,max:.36,color:'#b3c2c1',r:rand(2,5)});}
function usePotion(){if(potions<=0||player.hp>=player.maxHp)return;potions--;player.hp=Math.min(player.maxHp,player.hp+45);burst(player.x,player.y,'#bc6256',14);say('VITALITY RESTORED');}
function damagePlayer(n){if(player.invuln>0)return;player.hp-=n;player.invuln=.5;damageFlash=.2;screenShake=7;burst(player.x,player.y,'#bd5d50',8);if(player.hp<=0){player.hp=0;finish(false)}updateUI();}
function killEnemy(e){let i=enemies.indexOf(e);if(i<0)return;enemies.splice(i,1);totalKills++;waveKills++;burst(e.x,e.y,e.boss?'#ca9a52':'#9b5749',e.boss?24:9);orbs.push({x:e.x,y:e.y,r:5,value:e.boss?50:e.value,phase:rand(0,TAU)});if(Math.random()<.23||e.boss)drops.push({x:e.x+rand(-12,12),y:e.y+rand(-12,12),kind:Math.random()<.7?'gold':'potion',phase:rand(0,TAU)});if(e.boss){gold+=50;relicDrop();finish(true);return}if(waveKills>=waveTargets[wave-1]&&enemies.length===0){if(wave<4){state='between';setTimeout(()=>{if(state==='between'){wave++;waveKills=0;bossSpawned=false;player.hp=Math.min(player.maxHp,player.hp+18);player.mana=Math.min(player.maxMana,player.mana+12);spawnTimer=1;state='playing';say(`DESCENDING... FLOOR ${wave}`);updateUI()}},1800)}else{enemySpawn()}}updateUI();}
const relicPool=[{name:'Emberglass',icon:'◈',effect:'Knife damage +12%',apply:()=>player.damage*=1.12},{name:'Moonbone Charm',icon:'☾',effect:'Critical chance +5%',apply:()=>player.crit+=.05},{name:'Lantern Shard',icon:'✧',effect:'Maximum vitality +15',apply:()=>{player.maxHp+=15;player.hp+=15}},{name:'Ashen Spurs',icon:'⌁',effect:'Movement speed +8%',apply:()=>player.speed*=1.08}];
function relicDrop(){if(relics.length>=4)return;let choices=relicPool.filter(x=>!relics.includes(x)),r=choices[Math.floor(Math.random()*choices.length)];relics.push(r);r.apply();ui['weapon-name'].textContent=r.name;ui['weapon-stat'].textContent=r.effect;say(`RELIC FOUND: ${r.name.toUpperCase()}`);updateUI();}
function collectDrop(d){if(d.kind==='gold'){gold+=Math.floor(rand(8,19));say('GOLD GATHERED')}else{potions++;say('POTION FOUND')}drops.splice(drops.indexOf(d),1);updateUI();}
function burst(x,y,color,n){for(let i=0;i<n;i++){let a=rand(0,TAU),s=rand(25,150),life=rand(.2,.7);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life,max:life,color,r:rand(1.5,4)})}}
function gainXp(v){player.xp+=v;if(player.xp>=player.nextXp){player.xp-=player.nextXp;player.level++;player.nextXp=Math.floor(player.nextXp*1.42);player.hp=Math.min(player.maxHp,player.hp+12);player.mana=Math.min(player.maxMana,player.mana+15);showLevelUp()}updateUI();}
function showLevelUp(){state='levelup';const picks=[...upgrades].sort(()=>Math.random()-.5).slice(0,3);ui['upgrade-cards'].innerHTML='';for(const up of picks){let card=document.createElement('button');card.className='upgrade-card';card.innerHTML=`<div class="upgrade-icon">${up.icon}</div><h3>${up.title}</h3><p>${up.copy}</p><span class="choose">CHOOSE THIS BOON →</span>`;card.onclick=()=>{up.apply();ui['levelup-screen'].classList.add('hidden');state='playing';say(`${up.title.toUpperCase()} ACQUIRED`);updateUI()};ui['upgrade-cards'].appendChild(card)}ui['levelup-screen'].classList.remove('hidden');}
function finish(win){state=win?'won':'dead';ui['end-screen'].classList.remove('hidden');ui['end-kicker'].textContent=win?'THE CURSE IS BROKEN':'THE DESCENT ENDS';ui['end-title'].textContent=win?'THE VALE REMEMBERS':'THE HOLLOW CLAIMS ANOTHER';ui['end-copy'].textContent=win?`You felled the Dread Knight in ${formatTime(elapsed)} and gathered ${gold} gold.`:`You reached floor ${wave} and felled ${totalKills} restless souls. The Vale remembers the fallen.`;}
function formatTime(s){return `${Math.floor(s/60)}m ${Math.floor(s%60)}s`}

